def express(routes): return 'import express from "express";\nconst app = express();\napp.use(express.json({ limit: "10kb" }));\n'+routes+'\napp.listen(3000, "127.0.0.1");\n'
def fastify(routes): return 'import Fastify from "fastify";\nconst app = Fastify();\n'+routes+'\nawait app.listen({ port: 3000, host: "127.0.0.1" });\n'
def nest(methods, extra='', providers='[]', constructor=''):
 return 'import { Controller, Get, Post, Body, Param, Query, Module, Injectable, ParseIntPipe, DefaultValuePipe, BadRequestException, NotFoundException, HttpCode, Header, Redirect } from "@nestjs/common";\nimport { NestFactory } from "@nestjs/core";\n'+extra+'\n@Controller()\nclass LessonController {\n'+constructor+'\n'+methods+'\n}\n@Module({ controllers: [LessonController], providers: '+providers+' })\nclass AppModule {}\nasync function main() { const app = await NestFactory.create(AppModule); await app.listen(3000, "127.0.0.1"); }\nvoid main();\n'
course('express','Express.js','javascript','Examples use Express 5 and Node.js 20 or later.','In a practice folder run npm init -y and npm install express@5. Save one example as server.mjs and run node server.mjs. Use the stated URL on http://127.0.0.1:3000; stop with Ctrl+C before another example.','Express is a small Node.js tool for handling web requests and sending replies.',[
L('first-route','Reply to a request','A route pairs a method and path with a function. Open GET / to receive this text.',express('app.get("/", (req, res) => res.send("Hello, Asha!"));'),'Hello, Asha!','Change the reply text and restart the server.','The method and path must both match the route.'),
L('json','Send structured data','JSON is a text format for named data. GET /book returns a small object.',express('app.get("/book", (req, res) => res.json({ title: "Moon Trip", pages: 24 }));'),'{"title":"Moon Trip","pages":24}','Add a colour field to the object.','Use res.json for data so Express sets the JSON content type.'),
L('path-inputs','Read part of a path','A colon marks a path input. GET /hello/Ravi places Ravi in req.params.name.',express('app.get("/hello/:name", (req, res) => res.send(`Hi, ${req.params.name}!`));'),'Hi, Ravi!','Visit /hello/Asha.','Path inputs arrive as text; do not trust them as numbers automatically.'),
L('query-inputs','Read a query value','Query values follow ? in a URL. Visit GET /search?q=cat to read q.',express('app.get("/search", (req, res) => res.json({ term: typeof req.query.q === "string" ? req.query.q : "" }));'),'{"term":"cat"}','Visit /search with no query.','A query value can have an unexpected shape; check it before use.'),
L('post-json','Read a JSON body','POST can send a body. Send POST /books with Content-Type application/json and body {"title":"Moon Trip"}.',express('app.post("/books", (req, res) => {\n if (typeof req.body?.title !== "string") return res.status(400).json({ error: "Title needed" });\n return res.status(201).json({ title: req.body.title });\n});'),'{"title":"Moon Trip"}','Send an empty object and read the 400 reply.','express.json must run before routes that read a JSON body.'),
L('validation','Check a number','A route value needs checks before maths. GET /double/4 returns a doubled whole number.',express('app.get("/double/:n", (req, res) => {\n const n = Number(req.params.n);\n if (!Number.isSafeInteger(n)) return res.status(400).send("Use a whole number");\n return res.json({ answer: n * 2 });\n});'),'{"answer":8}','Visit /double/cat and read the error.','Number() can fail or produce decimals; check the allowed kind of value.'),
L('middleware','Run a shared step','Middleware runs before a later handler when it calls next. GET / shows the value this middleware placed in res.locals.',express('app.use((req, res, next) => { res.locals.school = "Oak School"; next(); });\napp.get("/", (req, res) => res.send(res.locals.school));'),'Oak School','Change the school name.','Middleware must send a response or call next; otherwise the request waits.'),
L('routers','Group related routes','A Router groups routes under a shared prefix. GET /api/books uses both the prefix and inner path.',express('const api = express.Router();\napi.get("/books", (req, res) => res.json(["Moon Trip"]));\napp.use("/api", api);'),'["Moon Trip"]','Add a /pets route to the same router.','The mounted prefix is part of the final URL.'),
L('status-codes','Say when an item is missing','A status code tells the client what happened. GET /books/99 returns 404 because this practice item is absent.',express('app.get("/books/:id", (req, res) => res.status(404).json({ error: "Book not found" }));'),'{"error":"Book not found"}','Use curl -i to inspect the 404 status too.','Set the status before sending the response body.'),
L('redirects','Point to another route','A redirect asks the client to visit another URL. GET /start points to /hello; a browser follows it.',express('app.get("/start", (req, res) => res.redirect(302, "/hello"));\napp.get("/hello", (req, res) => res.send("Welcome"));'),'Welcome','Inspect the first response Location header with curl -i.','A redirect is a new request, not an internal function call.'),
L('errors','Handle a route error','An error handler has four inputs. GET /broken throws an error, which the last handler turns into a clear reply.',express('app.get("/broken", (req, res) => { throw new Error("Practice failure"); });\napp.use((err, req, res, next) => res.status(500).json({ error: "Try again later" }));'),'{"error":"Try again later"}','Change the public error message.','Place error middleware after the routes and avoid exposing private error details.'),
L('not-found','Handle an unknown path','A final middleware can reply when no earlier route matched. GET /missing reaches this fallback.',express('app.get("/", (req, res) => res.send("Home"));\napp.use((req, res) => res.status(404).send("Page not found"));'),'Page not found','Visit / and compare the result.','Put the fallback last so it does not hide real routes.')])
course('fastify','Fastify','javascript','Examples use Fastify 5 and Node.js 20 or later.','In a practice folder run npm init -y and npm install fastify@5. Save one example as server.mjs and run node server.mjs. Use http://127.0.0.1:3000 and stop each server before the next example.','Fastify is a Node.js web framework with useful tools for route schemas, plugins and request tests.',[
L('first-route','Return a greeting','A Fastify handler can return a value directly. Open GET /.',fastify('app.get("/", async () => "Hello, Asha!");'),'Hello, Asha!','Change the returned greeting.','Return the result or send it with reply; do not do both.'),
L('json','Return an object','Fastify turns a returned object into JSON. Open GET /book.',fastify('app.get("/book", async () => ({ title: "Moon Trip", pages: 24 }));'),'{"title":"Moon Trip","pages":24}','Add a field.','Return data, not a hand-built JSON string, when possible.'),
L('params','Read a route input','A colon marks a path parameter. GET /hello/Ravi puts the name in request.params.',fastify('app.get("/hello/:name", async request => `Hi, ${request.params.name}!`);'),'Hi, Ravi!','Visit /hello/Asha.','Path values are text unless a schema converts and validates them.'),
L('query','Read a query string','Query input follows the question mark. GET /search?q=cat reads q.',fastify('app.get("/search", async request => ({ term: typeof request.query.q === "string" ? request.query.q : "" }));'),'{"term":"cat"}','Visit /search with no q.','Check query values rather than assuming they are always strings.'),
L('body','Read a JSON body','Fastify can parse JSON bodies. Send POST /books with application/json and {"title":"Moon Trip"}.',fastify('app.post("/books", async (request, reply) => {\n if (typeof request.body?.title !== "string") return reply.code(400).send({ error: "Title needed" });\n return reply.code(201).send({ title: request.body.title });\n});'),'{"title":"Moon Trip"}','Send an empty object and compare the response.','Content-Type tells the server how to read the body.'),
L('schemas','Validate a path value','A schema describes allowed data. GET /books/3 converts and checks id as a positive integer.',fastify('app.get("/books/:id", { schema: { params: { type: "object", required: ["id"], properties: { id: { type: "integer", minimum: 1 } } } } }, async request => ({ id: request.params.id }));'),'{"id":3}','Visit /books/cat and read the validation error.','Schemas must describe the input shape you actually expect.'),
L('hooks','Run a step before a handler','A preHandler hook runs before the route handler. GET / uses the request field set by the hook.',fastify('app.decorateRequest("school", "");\napp.addHook("preHandler", async request => { request.school = "Oak School"; });\napp.get("/", async request => request.school);'),'Oak School','Change the school value.','Use async hooks or callback hooks consistently; do not mix both styles.'),
L('decorators','Share a helper','decorate adds a named helper to the Fastify instance. GET / uses that helper.',fastify('app.decorate("greet", name => `Hi, ${name}!`);\napp.get("/", async () => app.greet("Ravi"));'),'Hi, Ravi!','Call the helper with Asha.','Register the helper before the route uses it.'),
L('plugins','Group routes in a plugin','register gives a plugin its own scope. A prefix puts its routes under /api. Open GET /api/books.',fastify('await app.register(async api => { api.get("/books", async () => ["Moon Trip"]); }, { prefix: "/api" });'),'["Moon Trip"]','Add another route inside the plugin.','The plugin prefix is part of the final URL.'),
L('response-schema','Choose response fields','A response schema can choose which fields are sent. GET /book keeps title and leaves out internalNote.',fastify('app.get("/book", { schema: { response: { 200: { type: "object", properties: { title: { type: "string" } } } } } }, async () => ({ title: "Moon Trip", internalNote: "draft" }));'),'{"title":"Moon Trip"}','Add pages to both the data and response schema.','A response schema is not a replacement for deciding which data is safe to return.'),
L('errors','Give a clear error reply','setErrorHandler handles errors from routes. GET /broken returns a simple public message.',fastify('app.setErrorHandler((error, request, reply) => reply.code(500).send({ error: "Try again later" }));\napp.get("/broken", async () => { throw new Error("Practice failure"); });'),'{"error":"Try again later"}','Inspect the 500 status.','Avoid showing private stack traces to clients.'),
L('injection-tests','Test without an open port','inject runs a request inside Fastify. This example prints the response body and closes the app without listening.','import Fastify from "fastify";\nconst app = Fastify();\napp.get("/score", async () => ({ score: 8 }));\nconst response = await app.inject({ method: "GET", url: "/score" });\nconsole.log(response.body);\nawait app.close();','{"score":8}','Change the route score and check the test output.','Close the app after tests so resources are released.')])
course('nestjs','NestJS','typescript','Examples use NestJS 10 or 11 with Node.js 20 or later.','Create a practice project with npx @nestjs/cli new school. Replace src/main.ts with one complete example and run npm run start. Use http://127.0.0.1:3000. The original app files are unused by these small examples.','NestJS organises a Node.js server into controllers, modules and shared services.',[
L('controllers','Make a controller route','A controller holds request handlers. @Get maps GET /hello to its method.',nest('@Get("hello") hello() { return "Hello, Asha!"; }'),'Hello, Asha!','Change the message.','A controller must be listed in a module to be used.'),
L('json','Return named data','Nest sends returned objects as JSON. Open GET /book.',nest('@Get("book") book() { return { title: "Moon Trip", pages: 24 }; }'),'{"title":"Moon Trip","pages":24}','Add an author field.','Let Nest write the returned object instead of writing a second response.'),
L('path-inputs','Read a route parameter','@Param reads a named part of the route. Open GET /hello/Ravi.',nest('@Get("hello/:name") hello(@Param("name") name: string) { return `Hi, ${name}!`; }'),'Hi, Ravi!','Visit /hello/Asha.','A TypeScript type does not validate a value sent over HTTP.'),
L('query-inputs','Read a query value','@Query reads the query string. Visit GET /search?q=cat.',nest('@Get("search") search(@Query("q") q: string = "") { return { term: q }; }'),'{"term":"cat"}','Try /search with no query.','Validate query input before using it for important work.'),
L('integer-pipe','Check and parse a number','ParseIntPipe reads an integer or rejects bad input. GET /double/4 uses the checked number.',nest('@Get("double/:n") twice(@Param("n", ParseIntPipe) n: number) { return { answer: n * 2 }; }'),'{"answer":8}','Visit /double/cat.','The pipe does the runtime check; the number annotation alone does not.'),
L('post-body','Read a request body','@Body supplies parsed JSON. Send POST /books with application/json and {"title":"Moon Trip"}.',nest('@Post("books") create(@Body() body: { title?: unknown }) { if (typeof body?.title !== "string") throw new BadRequestException("Title needed"); return { title: body.title }; }'),'{"title":"Moon Trip"}','Send an empty object.','Check body fields instead of trusting the TypeScript shape.'),
L('services','Share a service','A provider is a shared helper supplied by Nest. The controller asks for Books in its constructor. Open GET /book.',nest('@Get("book") book() { return this.books.title(); }','@Injectable()\nclass Books { title() { return "Moon Trip"; } }','[Books]','constructor(private readonly books: Books) {}'),'Moon Trip','Change the service title.','List Books in module providers so Nest can create it.'),
L('defaults','Supply a default query','DefaultValuePipe supplies a value before ParseIntPipe checks it. Open GET /page with no query.',nest('@Get("page") page(@Query("n", new DefaultValuePipe(1), ParseIntPipe) n: number) { return { page: n }; }'),'{"page":1}','Visit /page?n=3.','Pipe order matters: the default should happen before parsing.'),
L('status','Choose a reply status','@HttpCode changes a handler status. POST /check returns 200 instead of the usual Nest POST status.',nest('@Post("check") @HttpCode(200) check() { return { ready: true }; }'),'{"ready":true}','Use an HTTP client to inspect the 200 status.','A status describes the reply; it does not change the returned data.'),
L('headers','Add a response header','@Header adds metadata to a response. Open GET /note and inspect its Cache-Control header.',nest('@Get("note") @Header("Cache-Control", "no-store") note() { return "Private practice note"; }'),'Private practice note','Use curl -i to see Cache-Control: no-store.','Headers must be set before a response is sent.'),
L('redirects','Send a client to another route','@Redirect sends a location to the client. A browser following GET /start ends at /hello.',nest('@Get("start") @Redirect("/hello", 302) start() {}\n@Get("hello") hello() { return "Welcome"; }'),'Welcome','Inspect the initial 302 response.','A redirect makes the client send a new request.'),
L('errors','Report a missing item','A built-in exception creates an HTTP error response. GET /missing reports a missing book.',nest('@Get("missing") missing() { throw new NotFoundException("Book not found"); }'),'404 Not Found: Book not found','Try a custom missing-item message.','Use a suitable HTTP error instead of returning a success status for a failure.')])
